pub const SlotCounts = struct {
    slots: Symbol.SlotNamespace.CountsArray = Symbol.SlotNamespace.CountsArray.initFill(0),

pub fn unionMax(self: *SlotCounts, other: SlotCounts) void {
            var i: usize = 0;
            _ = &i;
            while ((i < self.slots.values.len)) : (i = (i + 1)) {
                if ((self.slots.values[@as(usize, @intCast(i))] < other.slots.values[@as(usize, @intCast(i))])) {
                    self.slots.values[cp_cast_int(usize, i)] = other.slots.values[@as(usize, @intCast(i))];
                }
            }
    }
};

pub const NameMinifier = struct {
    head: std.array_list.Managed(u8),
    tail: std.array_list.Managed(u8),

pub fn init(allocator: std.mem.Allocator) NameMinifier {
            return .{ .head = std.array_list.Managed(u8).init(allocator), .tail = std.array_list.Managed(u8).init(allocator) };
    }

pub fn numberToMinifiedName(self: *NameMinifier, name: *std.array_list.Managed(u8), _i: isize) !void {
            _ = name.clearRetainingCapacity();
            var i = _i;
            _ = &i;
            var j = (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54))))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54))))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54)))));
            _ = &j;
            _ = try name.appendSlice(self.head.items[j..(j + 1)]);
            i = @divFloor(i, 54);
            while ((i > 0)) {
                i = (i - 1);
                j = (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count))))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count))))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count)))));
                _ = try name.appendSlice(self.tail.items[j..(j + 1)]);
                i = @divFloor(i, char_freq_count);
            }
    }

pub fn defaultNumberToMinifiedName(allocator: std.mem.Allocator, _i: isize) ![]const u8 {
            var i = _i;
            _ = &i;
            var j = (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54))))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54))))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(@mod(i, 54))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, 54))) else cp_cast_int(i32, @mod(i, 54)))));
            _ = &j;
            var name = std.array_list.Managed(u8).init(allocator);
            _ = &name;
            _ = try name.appendSlice(default_head[j..(j + 1)]);
            i = @divFloor(i, 54);
            while ((i > 0)) {
                i = (i - 1);
                j = (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count))))) == .@"enum") cp_cast_int(usize, @intFromEnum((if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count))))) else cp_cast_int(usize, (if (comptime @typeInfo(@TypeOf(@mod(i, char_freq_count))) == .@"enum") cp_cast_int(i32, @intFromEnum(@mod(i, char_freq_count))) else cp_cast_int(i32, @mod(i, char_freq_count)))));
                _ = try name.appendSlice(default_tail[j..(j + 1)]);
                i = @divFloor(i, char_freq_count);
            }
            return name.items;
    }
    pub const default_head = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_$";
    pub const default_tail = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_$";
};

