pub const InlinedEnumValue = struct {
    raw_data: u64,

pub fn purifyNaN(value: f64) f64 {
            return (if (std.math.isNan(value)) pure_nan else value);
    }

pub fn encode(decoded: Decoded) InlinedEnumValue {
            const encoded: InlinedEnumValue = .{ .raw_data = (switch (decoded) {
.string => |ptr| @as(u48, @truncate(@intFromPtr(ptr))),
.number => |num| (@as(u64, @bitCast(purifyNaN(num))) + double_encode_offset),
}) };
            if (Environment.allow_assert) {
                _ = bun.assert((switch (encoded.decode()) {
.string => |str| (str == decoded.string),
.number => |num| (@as(u64, @bitCast(num)) == @as(u64, @bitCast(purifyNaN(decoded.number)))),
}));
            }
            return encoded;
    }

pub fn decode(encoded: InlinedEnumValue) Decoded {
            if ((encoded.raw_data > 281474976710655)) {
                return .{ .number = @bitCast((encoded.raw_data - double_encode_offset)) };
            } else {
                return .{ .string = @ptrFromInt(encoded.raw_data) };
            }
    }
    pub const Decoded = union(enum) {
        string: *E.String,
        number: f64,
    };
    const double_encode_offset = cp_shl(1, 49);
    const pure_nan_bits: u64 = 9221120237041090560;
    const pure_nan: f64 = @bitCast(pure_nan_bits);
};

pub const DeclaredSymbolList = struct {
    entries: bun.MultiArrayList(DeclaredSymbol) = .{},

pub fn refs(self: DeclaredSymbolList) []Ref {
            return self.entries.items(.@"ref");
    }

pub fn toOwnedSlice(self: *DeclaredSymbolList) DeclaredSymbolList {
            const copy = self.*;
            self.* = .{};
            return copy;
    }

pub fn clone(self: DeclaredSymbolList, allocator: std.mem.Allocator) !DeclaredSymbolList {
            return DeclaredSymbolList{ .entries = try self.entries.clone(allocator) };
    }

pub inline fn len(self: DeclaredSymbolList) usize {
            return self.entries.len;
    }

pub fn append(self: *DeclaredSymbolList, allocator: std.mem.Allocator, entry: DeclaredSymbol) !void {
            _ = try self.ensureUnusedCapacity(allocator, 1);
            _ = self.appendAssumeCapacity(entry);
    }

pub fn appendList(self: *DeclaredSymbolList, allocator: std.mem.Allocator, other: DeclaredSymbolList) !void {
            _ = try self.ensureUnusedCapacity(allocator, other.len());
            _ = self.appendListAssumeCapacity(other);
    }

pub fn appendListAssumeCapacity(self: *DeclaredSymbolList, other: DeclaredSymbolList) void {
            _ = self.entries.appendListAssumeCapacity(other.entries);
    }

pub fn appendAssumeCapacity(self: *DeclaredSymbolList, entry: DeclaredSymbol) void {
            _ = self.entries.appendAssumeCapacity(entry);
    }

pub fn ensureTotalCapacity(self: *DeclaredSymbolList, allocator: std.mem.Allocator, count: usize) !void {
            _ = try self.entries.ensureTotalCapacity(allocator, count);
    }

pub fn ensureUnusedCapacity(self: *DeclaredSymbolList, allocator: std.mem.Allocator, count: usize) !void {
            _ = try self.entries.ensureUnusedCapacity(allocator, count);
    }

pub fn clearRetainingCapacity(self: *DeclaredSymbolList) void {
            _ = self.entries.clearRetainingCapacity();
    }

pub fn deinit(self: *DeclaredSymbolList, allocator: std.mem.Allocator) void {
            _ = self.entries.deinit(allocator);
    }

pub fn initCapacity(allocator: std.mem.Allocator, capacity: usize) !DeclaredSymbolList {
            var entries: bun.MultiArrayList(DeclaredSymbol) = .{};
            _ = &entries;
            _ = try entries.ensureUnusedCapacity(allocator, capacity);
            return DeclaredSymbolList{ .entries = entries };
    }

pub fn fromSlice(allocator: std.mem.Allocator, entries: []const DeclaredSymbol) !DeclaredSymbolList {
            var res = try DeclaredSymbolList.initCapacity(allocator, entries.len);
            _ = &res;
            errdefer {
            _ = res.deinit(allocator);
            }
            for (cp_iter_slice(entries)) |entry| {
                _ = &entry;
                _ = res.appendAssumeCapacity(entry);
            }
            return res;
    }
};

pub const DeclaredSymbol = struct {
    @"ref": Ref,
    is_top_level: bool = false,

pub fn forEachTopLevelSymbolWithType(decls: *List, comptime Ctx: type, ctx: Ctx, comptime Fn: *const fn (Ctx, Ref) void) void {
            var entries = decls.entries.slice();
            _ = &entries;
            const is_top_level = entries.items(.is_top_level);
            const refs = entries.items(.@"ref");
            var i: usize = 0;
            _ = &i;
            while ((i < is_top_level.len)) : (i = (i + 1)) {
                if (is_top_level[@as(usize, @intCast(i))]) {
                    _ = @call(bun.callmod_inline, Fn, .{ ctx, refs[@as(usize, @intCast(i))] });
                }
            }
    }

pub fn forEachTopLevelSymbol(decls: *List, ctx: anytype, comptime Fn: anytype) void {
            _ = forEachTopLevelSymbolWithType(decls, @TypeOf(ctx), ctx, Fn);
    }
    pub const List = DeclaredSymbolList;
};

