pub fn NewBatcher(comptime Type: type) type {
        return struct {
    head: []Type,

pub fn init(allocator: std.mem.Allocator, count: usize) !@This() {
            const all = try allocator.alloc(Type, count);
            return .{ .head = all };
    }

pub fn done(self: *@This()) void {
            _ = bun.assert((self.head.len == 0));
    }

pub fn eat(self: *@This(), value: Type) *Type {
            return @ptrCast((&self.head.eat1(value).ptr));
    }

pub fn eat1(self: *@This(), value: Type) []Type {
            var prev = self.head[0..1];
            _ = &prev;
            prev[cp_cast_int(usize, 0)] = value;
            self.head = self.head[1..];
            return prev;
    }

pub fn next(self: *@This(), values: anytype) []Type {
            (self.head[0..values.len]).* = values;
            const prev = self.head[0..values.len];
            self.head = self.head[values.len..];
            return prev;
    }
};
}
